int time_to_str(double seconds, char *buf, size_t n) {
  int sec = floor(seconds);
  int hours = sec / 3600;
  int mins = (sec % 3600) / 60;
  sec = sec % 60;

  return snprintf(buf, n, "%02d:%02d:%02d", hours, mins, sec);
}

