static const char *avray__state_str(DecoderState st) {
  switch (st) {
  case DS_READY:
    return "READY";
  case DS_PLAYING:
    return "PLAYING";
  case DS_ERROR:
    return "ERROR";
  case DS_UNINIT:
    return "UNINIT";
  case DS_STARTUP:
    return "STARTUP";
  case DS_SHUTDOWN:
    return "SHUTDOWN";
  case DS_FILEEOF:
    return "FILEEOF";
  case DS_FINISHED:
    return "FINISHED";
  default:
    return "UNKNOWN?";
  }
}

static void avray__switch_dec_state(DecoderContext *ctx, DecoderState newState) {
  TraceLog(LOG_INFO, "AVRAYS: Switching to new state: %s", avray__state_str(newState));
  ctx->state = newState;
}

typedef enum {
  COMMAND_SEEK = 1,
  COMMAND_CLOSE,
} CommandType;

struct DecoderCommand {
  int (*dispatch)(DecoderContext *, struct DecoderCommand *);
  void (*free_me)(struct DecoderCommand *);
  CommandType c_type;
  size_t struct_size;
};

struct SeekCommand {
  struct DecoderCommand cmd;
  double target;
};

struct CloseFileCommand {
  struct DecoderCommand cmd;
};

static int avray__seek_command_dispatch(DecoderContext *ctx,
                                 struct DecoderCommand *cmd) {
  struct SeekCommand *c = (struct SeekCommand *)cmd;
  return avray__seek_to_frame(ctx, c->target);
}

static void avray__free_seek_command(struct DecoderCommand *cmd) { free(cmd); }

static struct SeekCommand *avray__make_seek_command(double target) {
  struct SeekCommand *result = malloc(sizeof(struct SeekCommand));
  result->target = target;
  result->cmd.c_type = COMMAND_SEEK;
  result->cmd.dispatch = &avray__seek_command_dispatch;
  result->cmd.free_me = &avray__free_seek_command;
  result->cmd.struct_size = sizeof(struct SeekCommand);
  return result;
}

static int avray__close_command_dispatch(DecoderContext *ctx,
                                  struct DecoderCommand *_) {
  return avray__exec_close_file(ctx, false);
}

static void avray__free_close_command(struct DecoderCommand *cmd) { free(cmd); }

static struct CloseFileCommand *avray__make_close_file_command() {
  struct CloseFileCommand *result = malloc(sizeof(struct CloseFileCommand));
  result->cmd.c_type = COMMAND_CLOSE;
  result->cmd.dispatch = &avray__close_command_dispatch;
  result->cmd.free_me = &avray__free_close_command;
  result->cmd.struct_size = sizeof(struct CloseFileCommand);
  return result;
}

static void avray__add_command_to_q(avray__LinkedQueue **q, struct DecoderCommand **cmd,
                             bool collapse) {
  if (collapse) {
    avray__LinkedQueue *mq = *q;
    while (mq->pnext) {
      struct DecoderCommand *d = (struct DecoderCommand *)mq->data;
      if (d->c_type == (*cmd)->c_type) {
        // just copy command on top of the previous one and delete unneeded
        // copy.
        memcpy(d, *cmd, (*cmd)->struct_size);
        (*cmd)->free_me(*cmd);
        *cmd = NULL;
        return;
      }
    }
  }
  *q = avray__queue_add(*q, *cmd);
}

// static DecoderContext *dc;
// ThreadType decoder_thread;
static int avray_continue_decoding(DecoderContext *);
static void *avray__decode_thread(void *ctx) {
  int result = 0;
  DecoderContext *dc = (DecoderContext *)ctx;
  static int call_count = 0;
  // wait for dc to be populated
  // while (!dc) {
  //   usleep(1000);
  // }
  do {
    switch (dc->state) {
    case DS_PLAYING:
      avray__mutex_lock(&dc->p->command_q_mtx);
      struct DecoderCommand *cmd = avray__queue_pop(&dc->p->command_queue);
      avray__mutex_unlock(&dc->p->command_q_mtx);
      if (cmd) {
        TraceLog(LOG_DEBUG, "AVRAYS: Command received");
        cmd->dispatch(dc, cmd);
        cmd->free_me(cmd);
      }
      // FALLTHROUGH
    case DS_STARTUP:
      result = avray_continue_decoding(dc);
      call_count++;
      if (result < 0) {
        if (result == AVERROR_EOF) {
          // dc->state = DS_SHUTDOWN;
          avray__switch_dec_state(dc, DS_FILEEOF);
        } else {
          char err_desc[256];
          av_strerror(result, err_desc, 256);
          TraceLog(LOG_ERROR, "Call count at err: %d, err: %d(%s)", call_count,
                   result, err_desc);
          // dc->state = DS_ERROR;
          avray__switch_dec_state(dc, DS_ERROR);
        }
      }
      // exit(EXIT_FAILURE);
      break;
    default:
      usleep(1000);
      break;
    }
  } while (dc->state != DS_SHUTDOWN);
  TraceLog(LOG_INFO, "AVRAYS: Decode THREAD shutdown.");
  return NULL;
}

