int avray_init_decoder(DecoderContext *ctx) {
  // if (dc != NULL) {
  //   return RESULT_ERROR;
  // }
  *ctx = (DecoderContext){};
  ctx->p = malloc(sizeof(struct DecoderPrivate));
  memset(ctx->p, 0, sizeof(struct DecoderPrivate));
  struct DecoderPrivate *p = ctx->p;
  p->audio_pull_timestamp = AVRAT_ZERO;

  avray__create_mutex(&p->image_buffer_mtx);
  avray__create_mutex(&p->audio_buffer_mtx);
  avray__create_mutex(&p->command_q_mtx);
  avray__create_mutex(&ctx->dc_mutex);
  avray__create_semaphore(&p->sem, 1);
  // avray__create_semaphore(&p->startup_sem, 0);

  int result = RESULT_OK;
  p->swr = swr_alloc();
  ERRCHECK2(p->swr, "Cant allocate audio resampler");

  p->fr = av_frame_alloc();
  ERRCHECK2(p->fr, "Cant allocate frame");
  p->fr_audio_target = av_frame_alloc();
  ERRCHECK2(p->fr_audio_target, "Cant allocate frame");
  p->fr_audio_target->ch_layout = (AVChannelLayout)AV_CHANNEL_LAYOUT_STEREO;
  p->fr_audio_target->format = AV_SAMPLE_FMT_FLT;

  p->pkt = av_packet_alloc();
  ERRCHECK2(p->pkt, "Cant allocate packet");

  ctx->vbuffer_timeline = make_timeline(sizeof(unsigned int), 120);
  ctx->abuffer_timeline = make_timeline(sizeof(unsigned int), 120);

  ctx->video_timest = 0;

  p->command_queue = avray__make_queue();

  // dc = ctx;
  // dc->state = DS_READY;
  avray__switch_dec_state(ctx, DS_READY);
  avray__thread_create(&p->decoder_thread, &avray__decode_thread, ctx);
  return result;
cleanup:
  avray__free_decoder_context(ctx);
  return result;
}

static int avray__time_probe_seek_pts(DecoderContext *ctx, int64_t *presult) {
  struct DecoderPrivate *p = ctx->p;

  int64_t timed = AV_TIME_BASE;
  // 1. Seek to the end of the file as much as we reasonably can
  int tres = avformat_seek_file(p->fmt_ctx, -1, 0, INT64_MAX, INT64_MAX, 0);
  TraceLog(LOG_DEBUG, "AVRAYS: avray__time_probe_seek_pts(): Timeprobe returned %d",
           tres);
  int result = RESULT_ERROR;
  if (tres != 0) {
    // Seeking failed, try to recover
    goto cleanup;
  }
  AVPacket *test_p = av_packet_alloc();
  int res = 0;
  int64_t max_pts = 0;
  while (true) {
    // 2. Read incoming frames until we can't anymore
    res = av_read_frame(p->fmt_ctx, test_p);
    if (res < 0) {
      // 2a. In which case, continue with 3.
      av_packet_unref(test_p);
      break;
    }
    if (test_p->stream_index == p->video_stream) {
      if (test_p->pts == AV_NOPTS_VALUE) {
        // No PTS values present, shortcut to the end
        result = RESULT_ERROR;
        av_packet_unref(test_p);
        goto cleanup;
      }
      if (test_p->pts > max_pts) {
        // 2b. Find maximum PTS in the packets received
        max_pts = test_p->pts;
        result = RESULT_OK;
      }
    }
    av_packet_unref(test_p);
  }

  // 3. Return timestamp if successful, then cleanup.
  if (result == RESULT_OK) {
    *presult = max_pts;
  }
cleanup:
  tres = avformat_seek_file(p->fmt_ctx, -1, 0, 0, timed, 0);
  TraceLog(LOG_DEBUG, "AVRAYS: Seek back %d", tres);
  // We might not be precisely at 00:00, so receive current timestamp from
  // streams.
  p->timestamp_reset_sm = TR_BEGIN;
  av_packet_free(&test_p);
  return result;
}

int avray_open_file(DecoderContext *ctx, const char *file_name) {
  int result = RESULT_OK;
  if (ctx->state == DS_FINISHED) {
    // we still have an open file so we can close it now
    // this will also switch state to DS_READY
    result = avray__exec_close_file(ctx, false);
    ERRCHECK("Unexpected error closing a file");
  }
  assert(ctx->state == DS_READY);
  struct DecoderPrivate *p = ctx->p;
  result = avformat_open_input(&p->fmt_ctx, file_name, NULL, NULL);
  if (result != 0) {
    return RESULT_CANT_OPEN;
  }
  ERRCHECK("Can't open file");

  result = avformat_find_stream_info(p->fmt_ctx, NULL);
  ERRCHECK("Cant find stream info");

  p->video_stream =
      av_find_best_stream(p->fmt_ctx, AVMEDIA_TYPE_VIDEO, -1, -1, NULL, 0);
  ERRCHECK2R(p->video_stream >= 0, RESULT_CANT_OPEN, "Cant find video stream");
  p->audio_stream =
      av_find_best_stream(p->fmt_ctx, AVMEDIA_TYPE_AUDIO, -1, -1, NULL, 0);
  ERRCHECK2R(p->audio_stream >= 0, RESULT_CANT_OPEN, "Cant find audio stream");
  AVCodecParameters *origin_par =
      p->fmt_ctx->streams[p->video_stream]->codecpar;
  AVCodecParameters *origin_par_audio =
      p->fmt_ctx->streams[p->audio_stream]->codecpar;

  TraceLog(
      LOG_DEBUG,
      "AVRAYS: Audio sample rate: %d, bits per sample: %d, channels: %d, "
      "frame "
      "size: %d",
      origin_par_audio->sample_rate, origin_par_audio->bits_per_coded_sample,
      origin_par_audio->ch_layout.nb_channels, origin_par_audio->frame_size);
  TraceLog(LOG_DEBUG, "AVRAYS: Video frame rate: %d/%d",
           origin_par->framerate.num, origin_par->framerate.den);

  const AVCodec *codec = avcodec_find_decoder(origin_par->codec_id);
  ERRCHECK2(codec, "Can't find decoder");
  const AVCodec *audio_codec = avcodec_find_decoder(origin_par_audio->codec_id);
  TraceLog(LOG_INFO, "AVRAYS: Video decoded with %s, audio with %s",
           codec->name, audio_codec->name);
  const char *duration_method;
  switch (p->fmt_ctx->duration_estimation_method) {
  case AVFMT_DURATION_FROM_PTS: ///< Duration accurately estimated from PTSes
    duration_method = "PTS";
    break;
  case AVFMT_DURATION_FROM_STREAM: ///< Duration estimated from a stream with a
                                   ///< known duration
    duration_method = "STREAM";
    break;
  case AVFMT_DURATION_FROM_BITRATE: ///< Duration estimated from bitrate (less
                                    ///< accurate)
    duration_method = "BITRATE";
    break;
  }
  double dur_est = (double)p->fmt_ctx->duration / AV_TIME_BASE;

  char msg[128];
  time_to_str(dur_est, msg, 128);
  TraceLog(LOG_INFO, "AVRAYS: Estimated duration %lf sec(%s) from %s", dur_est,
           msg, duration_method);

  if (p->fmt_ctx->duration_estimation_method == AVFMT_DURATION_FROM_BITRATE) {
    // Duration might not be accurate, estimate it with other methods instead
    int64_t pts;
    AVRational vid_tb = p->fmt_ctx->streams[p->video_stream]->time_base;
    result = avray__time_probe_seek_pts(ctx, &pts);
    if (result == RESULT_OK) {
      dur_est = av_q2d(av_mul_q((AVRational){pts, 1}, vid_tb));
    }
  }
  avray__mutex_lock(&ctx->dc_mutex);

  ctx->duration = dur_est;

  p->ctxv = avcodec_alloc_context3(codec);
  ERRCHECK2(p->ctxv, "Cant allocate memory for decoder context");
  p->ctxa = avcodec_alloc_context3(audio_codec);
  ERRCHECK2(p->ctxa, "Cant allocate memory for audio decoder");

  result = avcodec_parameters_to_context(p->ctxv, origin_par);
  ERRCHECK("Cant initiate video codec parameters");
  result = avcodec_parameters_to_context(p->ctxa, origin_par_audio);
  ERRCHECK("Cant initiate audio codec parameters");
  p->ctxv->thread_count = 4;
  p->ctxv->thread_type = FF_THREAD_SLICE;

  result = avcodec_open2(p->ctxv, codec, NULL);
  ERRCHECK("Cant open decoder");
  result = avcodec_open2(p->ctxa, audio_codec, NULL);
  ERRCHECK("Cant open audio decoder");

  const AVPixFmtDescriptor *pix_desc = av_pix_fmt_desc_get(p->ctxv->pix_fmt);
  TraceLog(LOG_INFO, "AVRAYS: Frame is %dx%d (%s)", p->ctxv->width,
           p->ctxv->height, pix_desc->name);
  ctx->video_width = p->ctxv->width;
  ctx->video_height = p->ctxv->height;
  if (p->ctxv->framerate.num != 0) {
    ctx->frame_rate = av_q2d(p->ctxv->framerate);
  } else {
    ctx->frame_rate = av_q2d(origin_par->framerate);
  }

  p->image_buffer_size =
      av_image_get_buffer_size(p->ctxv->pix_fmt, p->ctxv->width,
                               p->ctxv->height, 16) +
      sizeof(float);

  AVRational framerate = p->ctxv->framerate;
  size_t buffer_frames = (size_t)av_q2d(framerate);
  if (framerate.den == 1 && framerate.num == 0) {
    buffer_frames = RING_FRAMES;
  }

  p->image_buffer = avray__make_ringbuffer(p->image_buffer_size * buffer_frames);

  TraceLog(LOG_DEBUG,
           "AVRAYS: Audio codec data: sample format %s, sample rate %d, "
           "bytes per sample "
           "%d",
           av_get_sample_fmt_name(p->ctxa->sample_fmt), p->ctxa->sample_rate,
           av_get_bytes_per_sample(p->ctxa->sample_fmt));
  ctx->sample_rate = p->ctxa->sample_rate;

  TraceLog(LOG_DEBUG, "AVRAYS: video Time base is %d/%d",
           p->fmt_ctx->streams[p->video_stream]->time_base.num,
           p->fmt_ctx->streams[p->video_stream]->time_base.den);
  TraceLog(LOG_DEBUG, "AVRAYS: audio Time base is %d/%d",
           p->fmt_ctx->streams[p->audio_stream]->time_base.num,
           p->fmt_ctx->streams[p->audio_stream]->time_base.den);
  ctx->video_tb = p->fmt_ctx->streams[p->video_stream]->time_base;
  ctx->audio_tb = p->fmt_ctx->streams[p->audio_stream]->time_base;

  TraceLog(LOG_DEBUG, "AVRAYS: Codec framerate: %d/%d", p->ctxv->framerate.num,
           p->ctxv->framerate.den);
  // ctx->video_framerate = p->ctxv->framerate;
  ctx->pixel_format = origin_par->format;

  // ctx->state = DS_STARTUP;
  p->audio_pull_timestamp = AVRAT_ZERO;
  avray__switch_dec_state(ctx, DS_STARTUP);
  avray__mutex_unlock(&ctx->dc_mutex);

  return RESULT_OK;
cleanup:
  avray__exec_close_file(ctx, true);
  avray__mutex_unlock(&ctx->dc_mutex);
  return result;
}

static int avray__exec_close_file(DecoderContext *ctx, bool called_as_cleanup) {
  if (ctx->state != DS_STARTUP && ctx->state != DS_PLAYING &&
      ctx->state != DS_FINISHED && ctx->state != DS_FILEEOF &&
      !called_as_cleanup) {
    return RESULT_OK;
  }
  struct DecoderPrivate *p = ctx->p;
  int result = RESULT_OK;
  // If we were called for cleanup, the mutex is already locked.
  if (!called_as_cleanup) {
    avray__mutex_lock(&ctx->dc_mutex);
  }

  avray__mutex_lock(&p->audio_buffer_mtx);
  avray__mutex_lock(&p->image_buffer_mtx);

  ctx->pixel_format = 0;
  // ctx->video_framerate = AVRAT_ZERO;

  ctx->audio_tb = AVRAT_ZERO;
  ctx->video_tb = AVRAT_ZERO;
  ctx->sample_rate = 0;
  ctx->video_timest = 0;

  ctx->abytes_pulled = ctx->vbytes_pulled = ctx->abytes_written =
      ctx->vbytes_written = 0;

  avray__free_ringbuffer(&p->image_buffer);
  avray__free_ringbuffer(&p->audio_buffer);
  p->image_buffer_size = 0;
  p->audio_buffer_size = 0;

  ctx->video_height = ctx->video_width = 0;

  if (p->ctxa)
    avcodec_free_context(&p->ctxa);
  if (p->ctxv)
    avcodec_free_context(&p->ctxv);
  // if (p->fr_audio_target) {
  //   av_frame_free(&p->fr_audio_target);
  // }

  ctx->duration = 0;
  p->audio_stream = p->video_stream = 0;
  if (p->fmt_ctx)
    avformat_close_input(&p->fmt_ctx);

  // Reset other things as well
  if (p->pkt_populated) {
    av_packet_unref(p->pkt);
    p->pkt_populated = false;
  }
  p->fr_populated = p->fr_audio_populated = false;
  p->frame_is_audio = false;
  p->audio_configured = false;
  p->timestamp_reset_sm = TR_NONE;

  // Recreate semaphore, since we don't know its exact state
  avray__free_semaphore(&p->sem);
  avray__create_semaphore(&p->sem, 1);

  avray__switch_dec_state(ctx, DS_READY);

  avray__mutex_unlock(&p->image_buffer_mtx);
  avray__mutex_unlock(&p->audio_buffer_mtx);

  if (!called_as_cleanup) {
    avray__mutex_unlock(&ctx->dc_mutex);
  }

  return result;
}

// Feeds packet pkt to video or audio decoder
static int avray__feed_codec(struct DecoderPrivate *p, int *stream) {
  if (!p->pkt_populated) {
    return RESULT_OK;
  }

  int packet_stream = p->pkt->stream_index;
  if (stream) {
    *stream = packet_stream;
  }
  int result = 0;
  if (packet_stream == p->video_stream) {
    result = avcodec_send_packet(p->ctxv, p->pkt);
  } else if (packet_stream == p->audio_stream) {
    result = avcodec_send_packet(p->ctxa, p->pkt);
  }
  av_packet_unref(p->pkt);
  p->pkt_populated = false;
  return result;
}

static int avray__send_eof2codecs(struct DecoderPrivate *p) {
  int res1 = avcodec_send_packet(p->ctxv, NULL);
  int res2 = avcodec_send_packet(p->ctxa, NULL);
  if (res1 <= res2)
    return res1;
  return res2;
}

static int avray__pull_frame(struct DecoderPrivate *p) {
  if (p->fr_populated) {
    TraceLog(LOG_DEBUG, "AVRAYS: avray__pull_frame shortcut");
    return RESULT_OK;
  }

  // Try to receive audio frame, then a video frame
  int result = avcodec_receive_frame(p->ctxa, p->fr);
  if (result == 0) {
    p->fr_populated = true;
    p->frame_is_audio = true;
    return RESULT_OK;
  }
  result = avcodec_receive_frame(p->ctxv, p->fr);
  if (result == 0) {
    p->fr_populated = true;
    p->frame_is_audio = false;
  }
  return result;
}

static void avray__signal_startup(DecoderContext *ctx) {
  if (ctx->state != DS_STARTUP)
    return;
  // avray__semaphore_incr(&ctx->p->startup_sem);
  // ctx->state = DS_PLAYING;
  avray__switch_dec_state(ctx, DS_PLAYING);
}

static int avray__process_video_frame(DecoderContext *ctx) {
  struct DecoderPrivate *p = ctx->p;
  if (!p->fr_populated) {
    return RESULT_OK;
  }
  int result = RESULT_OK;
  uint8_t *write_loc =
      avray__write_ringbuffer_chunk_nocommit(&p->image_buffer, p->image_buffer_size);
  if (write_loc == NULL) {
    return RESULT_STALL;
  }
  avray__mutex_lock(&p->image_buffer_mtx);
  av_image_copy_to_buffer(write_loc + sizeof(float),
                          p->image_buffer_size - sizeof(float),
                          (uint8_t const *const *)p->fr->data, p->fr->linesize,
                          p->ctxv->pix_fmt, p->ctxv->width, p->ctxv->height, 1);

  AVRational video_time =
      av_mul_q(av_make_q(p->fr->best_effort_timestamp, 1), ctx->video_tb);
  (*(float *)write_loc) = (float)av_q2d(video_time);

  avray__write_ringbuffer_commit(&p->image_buffer, p->image_buffer_size);
  ctx->vbytes_written += p->image_buffer_size;
  avray__mutex_unlock(&p->image_buffer_mtx);
  p->fr_populated = false;
  return result;
}

static void avray__init_audio_buffer(struct DecoderPrivate *p) {
  assert(p->audio_buffer_size == 0);
  // TODO: check that p->fr and p->fr_audio_target are both valid audio frames
  assert(p->fr_audio_target->sample_rate != 0 && p->fr->sample_rate != 0);

  p->audio_buffer_size = p->fr_audio_target->nb_samples * sizeof(float) * 2;
  // How much is 1 second of sound? sample_rate samples
  size_t target_audio_ring_size = p->fr->sample_rate * sizeof(float) * 2;
  // This is now also the bitrate for sound
  size_t size_adj =
      p->audio_buffer_size - target_audio_ring_size % p->audio_buffer_size;
  target_audio_ring_size += size_adj;
  size_t audio_ring_size = target_audio_ring_size;
  // If the ringbuffer size is too small compared to what raylib
  // expects(4096 bytes) make it bigger.
  if (audio_ring_size < 4096 * 8) {
    audio_ring_size = 4096 * 8;
    // It still has to divide by audio_buffer_size.
    size_adj = p->audio_buffer_size - audio_ring_size % p->audio_buffer_size;
    audio_ring_size += size_adj;
  }
  p->audio_buffer = avray__make_ringbuffer(audio_ring_size);
  TraceLog(LOG_INFO, "AVRAYS: Audio buffer size is now %zu",
           p->audio_buffer.buf_size);
}

static void avray__init_swr_ifneeded(DecoderContext *ctx) {
  struct DecoderPrivate *p = ctx->p;
  // p->fr has to be an audio frame here
  if (p->audio_configured /*&&
      p->fr->nb_samples == p->fr_audio_target->nb_samples*/)
    return;

  /*if (p->audio_configured) {
    // If it was configured already, we have to reconfigure a few things
    av_frame_unref(p->fr_audio_target);

    p->fr_audio_target->ch_layout = (AVChannelLayout)AV_CHANNEL_LAYOUT_STEREO;
    p->fr_audio_target->format = AV_SAMPLE_FMT_FLT;
  }*/

  assert(ctx->sample_rate == p->fr->sample_rate);
  // ctx->sample_rate = p->fr->sample_rate;
  p->fr_audio_target->sample_rate = ctx->sample_rate;

  int result = swr_config_frame(p->swr, p->fr_audio_target, p->fr);
  TraceLog(LOG_DEBUG, "AVRAYS: SWR (re) initialized");
  assert(result == 0);

  p->audio_configured = true;
}

static int avray__process_audio_frame(DecoderContext *ctx) {
  struct DecoderPrivate *p = ctx->p;
  int result = RESULT_OK;
  bool fresh_frame = false;
  if (!p->fr_audio_populated) {
    avray__init_swr_ifneeded(ctx);
    assert(p->fr_populated);
    result = swr_convert_frame(p->swr, p->fr_audio_target, p->fr);
    // assert(swr_get_delay(p->swr, ctx->sample_rate) == 0);
    ERRCHECK("Cant convert audio frame");
    p->fr_populated = false;
    p->fr_audio_populated = true;
    fresh_frame = true;
  }

  if (p->audio_buffer_size == 0) {
    avray__init_audio_buffer(p);
  }

  avray__mutex_lock(&p->audio_buffer_mtx);
  size_t frame_size = p->fr_audio_target->nb_samples * sizeof(float) * 2;
  // fwrite(p->fr->data[0], 1, p->fr->nb_samples * 8, tempfile);
  // fflush(tempfile);
  size_t bytes_written = avray__write_to_ringbuffer(
      &p->audio_buffer, p->fr_audio_target->data[0], frame_size);
  ctx->abytes_written += bytes_written;

  if (bytes_written == 0) {
    // No space left in the buffer, indicate STALL condition
    avray__mutex_unlock(&p->audio_buffer_mtx);
    return RESULT_STALL;
  }

  if (p->timestamp_reset_sm == TR_BEGIN && fresh_frame) {
    // Get new timestamp from the audio frame
    p->new_timestamp =
        av_mul_q((AVRational){p->fr->best_effort_timestamp, 1}, ctx->audio_tb);
    TraceLog(LOG_DEBUG, "AVRAYS: Captured timestamp: %d / %d",
             p->new_timestamp.num, p->new_timestamp.den);
    p->timestamp_reset_sm = TR_TIMESTAMP_CAPTURED;
  }
  p->fr_audio_populated = false;
  avray__mutex_unlock(&p->audio_buffer_mtx);
cleanup:
  return result;
}

int avray_continue_decoding(DecoderContext *ctx) {
  if (ctx->state != DS_PLAYING && ctx->state != DS_STARTUP) {
    return RESULT_OK;
  }
  struct DecoderPrivate *p = ctx->p;

  // 1. Wait for decoding semaphore to release
  avray__semaphore_wait(&p->sem);
  avray__semaphore_incr(&p->sem);

  int result = RESULT_OK;

  // If we have any data in SWR buffer, try to drain it first
  if (p->audio_configured) {
    if (!p->fr_audio_populated && swr_get_delay(p->swr, ctx->sample_rate) > 0) {
      result = swr_convert_frame(p->swr, p->fr_audio_target, NULL);
      ERRCHECK("error extracting extra audio data");
      p->fr_audio_populated = true;
      p->frame_is_audio = true;
    }
  }

  // 2. If we already have a frame waiting from previous iteration, just use it
  if (!(p->fr_populated || p->fr_audio_populated)) {
    // 2a. try pulling a frame
    result = avray__pull_frame(p);

    while (result == AVERROR(EAGAIN)) {
      // 2b. frame doesn't exist, so we feed the decoder with the next packet
      assert(p->pkt_populated == false);
      result = av_read_frame(p->fmt_ctx, p->pkt);
      if (result < 0) {
        avray__send_eof2codecs(p);
      } else {
        p->pkt_populated = true;
        result = avray__feed_codec(p, NULL);
        ERRCHECK("Feed codec error");
      }
      // 2c. try pulling a frame again if we dont have it yet
      result = avray__pull_frame(p);
    }
  }
  if (result != RESULT_OK) {
    goto cleanup;
  }

  // 3. Process the frame that we received
  if (p->frame_is_audio) {
    result = avray__process_audio_frame(ctx);
  } else {
    result = avray__process_video_frame(ctx);
  }
  // 4. If the buffer is full, signal stall condition
  if (result == RESULT_STALL) {
    // 4a. If we are in a startup state, signal that we decoded enough.
    avray__signal_startup(ctx);
    avray__semaphore_wait(&p->sem);
    goto cleanup;
  }

cleanup:
  return result;
}

static void avray__try_unlock_decoder_sem(DecoderContext *ctx) {
  int sem_value;
  struct DecoderPrivate *p = ctx->p;
  avray__semaphore_get_value(&p->sem, &sem_value);
  if (sem_value == 0) {
    // we can advance semaphore if both buffers are less than 80% empty
    if (avray__ringbuffer_len(&p->image_buffer) < 0.8 * p->image_buffer.buf_size &&
        avray__ringbuffer_len(&p->audio_buffer) < 0.8 * p->audio_buffer.buf_size) {
      avray__semaphore_incr(&p->sem);
    }
  }
}

static void avray__try_move_to_finished_state(DecoderContext *ctx) {
  if (ctx->state != DS_FILEEOF)
    return;
  if (avray__ringbuffer_len(&ctx->p->audio_buffer) == 0 &&
      avray__ringbuffer_len(&ctx->p->image_buffer) == 0) {
    avray__switch_dec_state(ctx, DS_FINISHED);
  }
}

uint8_t *avray_pull_image(DecoderContext *ctx, float *timestamp) {
  struct DecoderPrivate *p = ctx->p;

  avray__mutex_lock(&p->image_buffer_mtx);
  // File could have been closed before we locked the mutex, or something else
  // might've happened
  if (ctx->state != DS_PLAYING && ctx->state != DS_FILEEOF) {
    // Even in this case we expect avray_release_image to be called,
    // so we don't unlock the mutex here.
    return NULL;
  }
  // printf("pull_image called\n");
  uint8_t *data = avray__read_ringbuffer_chunk(&p->image_buffer, p->image_buffer_size);
  if (data == NULL) {
    avray__try_move_to_finished_state(ctx);
    return data;
  }
  ctx->vbytes_pulled += p->image_buffer_size;
  *timestamp = *(float *)data;
  return data + sizeof(float);
}

void avray_release_image(DecoderContext *ctx) {
  avray__try_unlock_decoder_sem(ctx);
  avray__mutex_unlock(&ctx->p->image_buffer_mtx);
}

int avray_pull_audio(DecoderContext *ctx, void *audio_buffer,
                     unsigned int frames) {
  // printf("pull_audio %d called\n", frames);
  struct DecoderPrivate *p = ctx->p;
  if (ctx->state != DS_PLAYING && ctx->state != DS_FILEEOF) {
    return 0;
  }
  avray__mutex_lock(&p->audio_buffer_mtx);
  // File could've been closed while we were waiting for mutex to release.
  // So we have to check the state again.
  if (ctx->state != DS_PLAYING && ctx->state != DS_FILEEOF) {
    avray__mutex_unlock(&p->audio_buffer_mtx);
    return 0;
  }
  if (!p->audio_configured) {
    avray__mutex_unlock(&p->audio_buffer_mtx);
    return 0;
  }
  size_t bytes_to_read = frames * 2 * sizeof(float);
  int result = avray__read_ringbuffer(&p->audio_buffer, audio_buffer, bytes_to_read);
  ctx->abytes_pulled += result;
  avray__try_unlock_decoder_sem(ctx);
  const int bytes_per_frame = sizeof(float) * 2;
  if (p->timestamp_reset_sm == TR_TIMESTAMP_CAPTURED) {
    p->audio_pull_timestamp = p->new_timestamp;
    p->timestamp_reset_sm = TR_FINISHED;
  } else {
    p->audio_pull_timestamp =
        av_add_q(p->audio_pull_timestamp,
                 av_make_q(result / bytes_per_frame, ctx->sample_rate));
  }
  if (result == 0) {
    avray__try_move_to_finished_state(ctx);
  }
  avray__mutex_unlock(&p->audio_buffer_mtx);
  return result;
}

static int avray__seek_to_frame(DecoderContext *ctx, double ts) {
  int64_t time = floor(ts * AV_TIME_BASE);
  int64_t time_dt = AV_TIME_BASE;

  struct DecoderPrivate *p = ctx->p;
  avray__mutex_lock(&p->audio_buffer_mtx);
  avray__mutex_lock(&p->image_buffer_mtx);
  TraceLog(LOG_DEBUG, "AVRAYS: seeking to %ld", time);
  int result = avformat_seek_file(p->fmt_ctx, -1, time - time_dt, time,
                                  time + time_dt, 0);
  TraceLog(LOG_DEBUG, "AVRAYS: Seek file (+-1) returns %d", result);
  if (result != 0) {
    result = avformat_seek_file(p->fmt_ctx, -1, time - 5 * time_dt, time,
                                time + 5 * time_dt, 0);
    TraceLog(LOG_DEBUG, "AVRAYS: Seek file (+-5) returns %d", result);
  }
  if (result != 0) {
    result = avformat_seek_file(p->fmt_ctx, -1, time - 10 * time_dt, time,
                                time + 10 * time_dt, 0);
    TraceLog(LOG_DEBUG, "AVRAYS: Seek file (+-10) returns %d", result);
  }
  if (result != 0) {
    result = avformat_seek_file(p->fmt_ctx, -1, time - 20 * time_dt, time,
                                time + 20 * time_dt, 0);
    TraceLog(LOG_DEBUG, "AVRAYS: Seek file (+-20) returns %d", result);
  }
  if (result != 0) {
    result = avformat_seek_file(p->fmt_ctx, -1, 0, time, INT64_MAX, 0);
    TraceLog(LOG_DEBUG, "AVRAYS: Seek file (+-INF) returns %d", result);
  }
  if (result != 0) {
    avray__mutex_unlock(&p->image_buffer_mtx);
    avray__mutex_unlock(&p->audio_buffer_mtx);
    return result;
  }
  avcodec_flush_buffers(p->ctxv);
  avcodec_flush_buffers(p->ctxa);
  if (ctx->state != DS_STARTUP) {
    // repurpose "startup" tech here
    assert(ctx->state == DS_PLAYING);
    // ctx->state = DS_STARTUP;
    avray__switch_dec_state(ctx, DS_STARTUP);
    // decrease semaphore count, it should now become 0
    // avray__semaphore_wait(&p->startup_sem);
  }
  avray__ringbuffer_flush(&p->audio_buffer);
  avray__ringbuffer_flush(&p->image_buffer);
  p->timestamp_reset_sm = TR_BEGIN;
  p->new_timestamp = (AVRational){0, 1};
  p->fr_audio_populated = false;
  p->fr_populated = false;
  ctx->video_timest = 0;
  if (p->pkt_populated) {
    p->pkt_populated = false;
    av_packet_unref(p->pkt);
  }
  avray__try_unlock_decoder_sem(ctx);
  avray__mutex_unlock(&p->image_buffer_mtx);
  avray__mutex_unlock(&p->audio_buffer_mtx);
  return RESULT_OK;
}

void avray_seek_to_frame(DecoderContext *ctx, double ts) {
  struct DecoderPrivate *p = ctx->p;
  avray__mutex_lock(&p->command_q_mtx);

  struct SeekCommand *cmd = avray__make_seek_command(ts);
  TraceLog(LOG_DEBUG, "AVRAYS: Command seek added");
  // p->command_queue = avray__queue_add(p->command_queue, cmd);
  avray__add_command_to_q(&p->command_queue, (struct DecoderCommand **)&cmd, true);

  avray__mutex_unlock(&p->command_q_mtx);
}

void avray_close_file(DecoderContext *ctx) {
  struct DecoderPrivate *p = ctx->p;
  avray__mutex_lock(&p->command_q_mtx);

  struct CloseFileCommand *cmd = avray__make_close_file_command();
  TraceLog(LOG_DEBUG, "AVRAYS: Command closefile added");
  // p->command_queue = avray__queue_add(p->command_queue, cmd);
  avray__add_command_to_q(&p->command_queue, (struct DecoderCommand **)&cmd, true);

  avray__mutex_unlock(&p->command_q_mtx);
}

bool avray_is_decoder_stopped(DecoderContext *ctx) {
  return ctx->state == DS_SHUTDOWN /* || ctx->state == DS_FINISHED*/ ||
         ctx->state == DS_ERROR;
}

void avray__free_decoder_context(DecoderContext *ctx) {
  // TODO: join the thread here?
  // for now we just assume that the thread was either joined, or never started
  struct DecoderPrivate *p = ctx->p;

  if (p->command_queue) {
    avray__queue_free(p->command_queue);
    p->command_queue = NULL;
  }

  avray__free_semaphore(&p->sem);
  // avray__free_semaphore(&p->startup_sem);
  avray__free_mutex(&p->command_q_mtx);
  avray__free_mutex(&p->audio_buffer_mtx);
  avray__free_mutex(&p->image_buffer_mtx);
  avray__free_mutex(&ctx->dc_mutex);
  avray__free_ringbuffer(&p->image_buffer);
  avray__free_ringbuffer(&p->audio_buffer);
  if (p->pkt) {
    av_packet_free(&p->pkt);
  }
  if (p->fr_audio_target) {
    av_frame_free(&p->fr_audio_target);
  }
  if (p->fr) {
    av_frame_free(&p->fr);
  }
  if (p->ctxa) {
    avcodec_free_context(&p->ctxa);
  }
  if (p->ctxv) {
    avcodec_free_context(&p->ctxv);
  }
  if (p->swr) {
    swr_free(&p->swr);
  }
  if (p->fmt_ctx) {
    avformat_close_input(&p->fmt_ctx);
  }
  free(p);
  ctx->p = NULL;
}

void avray_update_timelines(DecoderContext *ctx) {
  struct DecoderPrivate *p = ctx->p;
  unsigned int *tl_loc = (unsigned int *)timeline_push(&ctx->abuffer_timeline);
  if (p->audio_buffer_size > 0) {
    *tl_loc = avray__ringbuffer_len(&p->audio_buffer) * 100 / p->audio_buffer.buf_size;
  } else {
    *tl_loc = 0;
  }
  tl_loc = (unsigned int *)timeline_push(&ctx->vbuffer_timeline);
  if (p->image_buffer.buf_size > 0) {
    *tl_loc = avray__ringbuffer_len(&p->image_buffer) * 100 / p->image_buffer.buf_size;
  } else {
    *tl_loc = 0;
  }
}

